import "core-js/modules/es.array.push.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import AddTerritory from "@/components/SettingsDialogs/AddTerritory.vue";
import EditTerritory from "@/components/SettingsDialogs/EditTerritory.vue";
import DeleteTerritory from "@/components/SettingsDialogs/DeleteTerritory.vue";
import { create_list_edit_territories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    AddTerritory,
    SnackBar,
    EditTerritory,
    DeleteTerritory
  },
  data() {
    return {
      territoryHeaders: [{
        title: "Name",
        value: "territory_name"
      }, {
        title: "Head",
        value: "territory_head_name"
      }, {
        title: "Created By",
        value: "territory_created_by"
      }, {
        title: "Action",
        value: "actions"
      }],
      fixed: true,
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      height: 0,
      page: 1,
      currentPage: 1,
      totalItems: 0,
      itemsPerPage: 20,
      createTerritoryDialog: false,
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      editTerritoryDialogue: false,
      rowInfo: {},
      deleteTerritoryDialogue: false
    };
  },
  created() {
    this.fetch_territories();
  },
  computed: {
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  async mounted() {
    this.CommonVuetifyObj = useDisplay();
  },
  methods: {
    add_territory() {
      this.componentCheck = 1;
      this.createTerritoryDialog = true;
    },
    edit_territory(value) {
      this.rowInfo = value;
      this.componentCheck = 2;
      this.editTerritoryDialogue = true;
    },
    open_deletedailog(value) {
      this.rowInfo = value;
      this.componentCheck = 3;
      this.deleteTerritoryDialogue = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createTerritoryDialog = false;
      this.editTerritoryDialogue = false;
      this.deleteTerritoryDialogue = false;
      this.fetch_territories();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_territories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_territories, {
          input: {
            action_type: "LIST",
            organization_id: data.organization.organization_id
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_edit_territories);
        this.tableLoading = false;
        this.tableData = response.data;
        this.totalItems = this.tableData.length;
      } catch (error) {
        this.tableLoading = false;
        this.totalItems = 0;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
